function renderChanges(){const s=current(),changes=allChanges().filter(c=>c.segment.id===s.id);$('miniDemo').className='mini-demo '+value(s.id,'components','visualStyle')+' '+value(s.id,'components','styleVariant');$('changeList').innerHTML=changes.length?changes.map(c=>`<div class="change-item"><button class="revert" data-revert-module="${c.module}" data-revert-key="${c.key}">恢复原值</button><b>${moduleName(c.module)} · ${OPTIONS[c.module].find(o=>o[0]===c.key)[1]}</b><code>${esc(labelFor(c.module,c.key,c.from))} → ${esc(labelFor(c.module,c.key,c.to))}</code></div>`).join(''):'<div class="empty">还没有配置建议。<br>在右侧展开任一模块，试着调整一个选项。</div>';}
