function exportData(){return{schemaVersion:1,type:'video-review-suggestions',prototype:true,createdAt:new Date().toISOString(),project:{id:'save-first-6s',revision:'prototype-source-v1',sourceVideo:'sample.mp4',sourceVideoSha256:SOURCE_HASH,fps:60,durationSeconds:6},segmentation:{source:'prototype-example-from-script-events',segments:SEGMENTS.map(s=>({id:s.id,shotIds:['s1'],title:s.title,startFrame:Math.round(s.start*60),endFrame:Math.round(s.end*60),endExclusive:true,event:s.event,design:s.design}))},configSuggestions:allChanges().map((c,i)=>({id:c.segment.id+'.'+c.module+'.'+c.key,target:{segmentId:c.segment.id,shotId:'s1',module:c.module,objectId:c.module==='components'?'version-diagram':null,event:c.segment.event},sourceRef:{file:c.module==='audio'?'production-plan.json':'storyboard.json',stableId:c.module==='audio'?'save-first-production':'s1',field:c.module==='audio'?'/audio':'/intent'},requestedField:c.key,originalValue:c.from,suggestedValue:c.to,scope:'current-segment',continuityReviewSegments:SEGMENTS.filter(s=>s.id!==c.segment.id).map(s=>s.id),execution:'requires-source-review-and-implementation'})),comments:state.comments.map(c=>({...c,anchor:c.anchor?{space:'video-normalized',...c.anchor}:null})),summary:{configSuggestions:allChanges().length,openComments:state.comments.filter(c=>!c.resolved).length,resolvedComments:state.comments.filter(c=>c.resolved).length},instruction:'核对源工程版本、实现边界与相邻片段连续性。此文件不是可直接应用的工程补丁；不要将示例字段当作已支持参数。'}}
