function atomConfig(module){return Object.fromEntries(Object.keys(DEFAULTS[module]).map(k=>[k,value(state.selected,module,k)]))}
function sameConfig(a,b){return JSON.stringify(Object.entries(a).sort())===JSON.stringify(Object.entries(b).sort())}
function findFavorite(module){return favorites.find(f=>f.module===module&&f.design===current().design[module]&&sameConfig(f.configuration,atomConfig(module)))}
async function favoriteRequest(path,body){const r=await fetch('/api/favorites'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Review-Client':'segment-review-v2'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(data.error||'收藏服务不可用');return data}
function acceptFavorites(data){favorites=data.items;favoriteStorage=data.storage;favoritesOnline=true;renderFavoriteList();renderDesign();renderInspector()}
async function loadFavorites(){try{acceptFavorites(await favoriteRequest(''))}catch(e){favoritesOnline=false;$('favoriteStorage').textContent='收藏服务未连接。请使用 server.py 启动本地工作台；尚未写入文件。';$('favoriteCount').textContent='未连接'}}
function renderFavoriteList(){const q=$('favoriteSearch').value.toLowerCase(),mod=$('favoriteModule').value;const list=favorites.filter(f=>(mod==='all'||f.module===mod)&&JSON.stringify([f.title,f.design,f.configuration]).toLowerCase().includes(q));$('favoriteCount').textContent=favorites.length;$('sideFavoriteCount').textContent=favorites.length;if(favoriteStorage)$('favoriteStorage').textContent=`已写入 ${favoriteStorage.path} · ${favorites.length}/${favoriteStorage.maxItems} 项 · ${(favoriteStorage.bytes/1024).toFixed(1)} KiB / 2 MiB · 不含媒体`;
$('favoriteList').innerHTML=list.length?list.map(f=>`<article class="favorite-item"><div class="favorite-symbol">★</div><div><h3>${esc(f.title)} <span class="badge ${f.approval.basis==='proposed-config'?'orange':''}">${f.approval.basis==='proposed-config'?'建议偏好 · 未渲染':'当前原子设计认可'}</span></h3><p>${esc(f.design)}</p><div class="favorite-config">${Object.entries(f.configuration).map(([k,v])=>`<span>${esc(k)}: ${esc(v)}</span>`).join('')}</div><div class="favorite-bottom"><small>${moduleName(f.module)} · ${f.sources.length} 个来源 · ${f.createdAt.slice(0,10)} · 仅引用</small><button data-use-favorite="${f.id}">引用配置</button><button data-remove-favorite="${f.id}">取消收藏</button></div></div></article>`).join(''):'<div class="empty">'+(favorites.length?'没有匹配的收藏。':'还没有收藏。点击模块行右侧的 ☆，保存满意的设计。<br>不会自动把样片或示例配置记成你的偏好。')+'</div>'}
async function toggleFavorite(module){if(!favoritesOnline){await loadFavorites();if(!favoritesOnline)return toast('收藏服务未连接，未写入仓库')}const existing=findFavorite(module);try{if(existing){acceptFavorites(await favoriteRequest('/remove',{id:existing.id}));toast('已取消收藏，仓库文件已更新');return}const s=current(),proposed=changeCountForModule(s.id,module)>0;const payload={module,title:moduleName(module)+' · '+(module==='components'?'版本关系图':s.title.split(' · ')[1]),design:s.design[module],configuration:atomConfig(module),basis:proposed?'proposed-config':'current-render',source:{projectId:'save-first-6s',segmentId:s.id,shotId:'s1',event:s.event,sourceVideoSha256:SOURCE_HASH,timeSeconds:s.preview}};acceptFavorites(await favoriteRequest('/add',payload));toast(proposed?'建议偏好已写入收藏夹，已标注未渲染':'此原子设计已收藏到本地仓库')}catch(e){toast(e.message)}}
async function openFavorites(){$('favoritesDialog').showModal();await loadFavorites()}
$('favoriteModule').innerHTML='<option value="all">全部模块</option>'+MODULES.map(([id,n])=>`<option value="${id}">${n}</option>`).join('');$('favoritesBtn').onclick=openFavorites;$('sideFavorites').onclick=openFavorites;$('closeFavorites').onclick=()=>$('favoritesDialog').close();$('favoriteSearch').oninput=renderFavoriteList;$('favoriteModule').onchange=renderFavoriteList;
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.favorite){b.disabled=true;try{await toggleFavorite(b.dataset.favorite)}finally{b.disabled=false}}if(b.dataset.removeFavorite){try{acceptFavorites(await favoriteRequest('/remove',{id:b.dataset.removeFavorite}));toast('已取消收藏，未删除原项目素材')}catch(err){toast(err.message)}}if(b.dataset.useFavorite){const f=favorites.find(x=>x.id===b.dataset.useFavorite);if(!f)return;for(const[k,v]of Object.entries(f.configuration)){if(!OPTIONS[f.module].some(o=>o[0]===k&&o[2].some(c=>c[0]===v)))return toast('收藏包含当前原型不支持的字段，请回源适配')}state.changes[state.selected]??={};state.changes[state.selected][f.module]={};for(const[k,v]of Object.entries(f.configuration))if(v!==DEFAULTS[f.module][k])state.changes[state.selected][f.module][k]=v;state.openModule=f.module;state.tab='changes';persist();render();$('favoritesDialog').close();toast('已引用为当前片段建议，原片未改动')}});
function updateCounts(){$('totalCount').textContent=allChanges().length+state.comments.filter(c=>!c.resolved).length;$('changeCount').textContent=changeCount(state.selected);$('commentCount').textContent=commentCount(state.selected)}
function render(){renderList();renderDesign();renderInspector();renderChanges();renderComments();renderTabs();updateCounts()}
const initialVideo=document.querySelector('video');if(initialVideo.readyState>=1)seek(current().preview);else initialVideo.addEventListener('loadeddata',()=>seek(current().preview),{once:true});

$('zoomBtn').onclick=()=>{const on=document.querySelector('.workspace').classList.toggle('large-preview');$('zoomBtn').setAttribute('aria-pressed',String(on));$('zoomBtn').textContent=on?'⛶ 收起':'⛶ 放大'};
